void enterMelodicSlices(){const juce::ScopedLock guard(lock);beginEdit();setPlaybackMode(0);if(extractionInstrument)extractionInstrument->clearVoices();melodicSliceMode=true;melodicSequenceCreated=false;sequenceEnabled=sequenceView=false;sequenceWasPlaying=false;edited(false);endEdit();}
void setMelodicNote(int index,int note){const juce::ScopedLock guard(lock);if(!juce::isPositiveAndBelow(index,(int)slices.size()))return;slices[index].melodicNote=juce::jlimit(-1,127,note);slices[index].melodicManual=true;edited(false);}
void auditionMelodicSlice(int index){if(!melodicSliceMode||!melodicAuditionEnabled||!auditionInstrument()||!juce::isPositiveAndBelow(index,(int)slices.size()))return;auto& instrument=*auditionInstrument();instrument.clearVoices();melodicAuditionNote=-1;auto& slice=slices[index];if(slice.melodicNote<0)return;melodicPreviewPitch=juce::jlimit(0,127,slice.melodicNote+keyTranspose());instrument.shotLegato=false;double nativePitch=instrument.pitchSemitones;instrument.pitchSemitones+=pitchSemitones;instrument.shotNoteOn(melodicPreviewPitch,.85f);instrument.pitchSemitones=nativePitch;melodicAuditionNote=melodicPreviewPitch;melodicAuditionRemaining=juce::jmax(1,(int)std::round((slice.audibleEnd(audio->rate)-slice.start)/audio->rate*outputRate));}
void renderMelodicAudition(juce::AudioBuffer<float>& out,juce::MidiBuffer& midi,bool sequencePlayback=false){if(!melodicSliceMode||!auditionInstrument())return;auto& instrument=*auditionInstrument();instrument.outputRate=outputRate;if(!sequencePlayback){melodicPreviewMidi.clear();if(melodicAuditionNote>=0){if(melodicAuditionRemaining<out.getNumSamples()){melodicPreviewMidi.addEvent(juce::MidiMessage::noteOff(1,melodicAuditionNote),juce::jmax(0,melodicAuditionRemaining));melodicAuditionNote=-1;}else melodicAuditionRemaining-=out.getNumSamples();}}double gain=instrument.shotGainDb,nativePitch=instrument.pitchSemitones;instrument.shotGainDb=gain+melodicAuditionGainDb;instrument.pitchSemitones+=pitchSemitones;instrument.renderShots(out,sequencePlayback?midi:melodicPreviewMidi);instrument.shotGainDb=gain;instrument.pitchSemitones=nativePitch;}
bool createMelodicSequence(){const juce::ScopedLock guard(lock);if(!melodicSliceMode||!audio)return false;SequenceClip clip;std::vector<SfzRegion> rows;double spb=audio->rate*60/sourceBpm,beats=loopBeats();clip.bars=juce::jmax(1,(int)std::ceil(beats/4-1e-8));for(auto& slice:slices){int a=juce::jmax(slice.start,regionStart()),b=juce::jmin(slice.audibleEnd(audio->rate),regionEnd());if(slice.muted||slice.melodicNote<0||b<=a)continue;SfzRegion region;region.source=audio;region.root=slice.melodicNote;region.start=region.loopStart=a;region.end=region.loopEnd=b;region.roundRobinGroup=region.root+1;region.melodicSliceId=(int)rows.size()+1;region.pitchMethod=slice.melodicManual?"Manual":"Detected slice";region.pitchConfidence=slice.melodicManual?1:0;region.endFadeMs=slice.endFadeMs;region.gain=juce::Decibels::decibelsToGain(slice.gainDb);rows.push_back(region);double beat=std::fmod((a-startMarker)/spb+beats*2,beats);clip.notes.push_back({clip.nextId++,slice.melodicNote,100,1,beat,juce::jmin((b-a)/spb,beats-beat),region.melodicSliceId});}if(rows.empty())return false;MultiMapping::autoMap(rows);clip.key=SequenceClip::inferKey(clip.notes,clip.minor);if(loopKey>=0)clip.key=loopKey;auto sourceKey=LibraryStore::resolveMusicalKey(juce::File(audio->path),{loopKey,-1});if(sourceKey.known()){clip.key=sourceKey.root;if(sourceKey.quality>=0)clip.minor=sourceKey.minor();}clip.revision=sequence.revision+1;beginEdit();clearVoices();publishMulti(std::move(rows));melodicTimbre=0;multiRoundRobinMode=0;multiRRNext.fill(0);multiRRLast.fill(-1);melodicSliceMode=false;melodicSequenceCreated=true;melodicAuditionNote=-1;if(extractionInstrument)extractionInstrument->clearVoices();stretchMode=warpMode=trackMode=false;trackPlayer.clearSource();extractionActive=extractionMidiAudition=false;shotMono=shotLegato=shotLoop=false;shotEnvelope={0,0,1,.25f};sequence=std::move(clip);sequenceAutoQuantize=false;sequenceEnabled=sequenceView=playMode=true;sequenceWasPlaying=false;edited(false);endEdit();return true;}
